package com.clantenure;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ClanTenurePluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(ClanTenurePlugin.class);
		RuneLite.main(args);
	}
}

package com.clantenure;

import java.time.LocalDate;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class MemberRulesTest
{
	private static final LocalDate TODAY = LocalDate.of(2026, 8, 6);

	private static MemberRules parse(String ignored, String joinDates)
	{
		return MemberRules.parse(ignored, joinDates, TODAY);
	}

	@Test
	public void emptyConfigIgnoresNobodyAndOverridesNothing()
	{
		final MemberRules rules = parse("", "");

		assertTrue(rules.isEmpty());
		assertFalse(rules.isIgnored("Zezima"));
		assertNull(rules.joinDateFor("Zezima"));
		assertEquals(0, rules.getWarnings().size());
	}

	@Test
	public void nullConfigIsTreatedAsEmpty()
	{
		final MemberRules rules = MemberRules.parse(null, null, TODAY);

		assertTrue(rules.isEmpty());
	}

	@Test
	public void ignoredMembersAcceptCommasAndNewLines()
	{
		final MemberRules rules = parse("Alt One, Alt Two\nAlt Three", "");

		assertTrue(rules.isIgnored("Alt One"));
		assertTrue(rules.isIgnored("Alt Two"));
		assertTrue(rules.isIgnored("Alt Three"));
		assertFalse(rules.isIgnored("Zezima"));
	}

	@Test
	public void nameMatchingIgnoresCaseAndSpacing()
	{
		final MemberRules rules = parse("Iron Mammal", "zezima=2015-03-14");

		assertTrue(rules.isIgnored("iron   mammal"));
		assertTrue(rules.isIgnored("IRON MAMMAL"));
		assertEquals(LocalDate.of(2015, 3, 14), rules.joinDateFor("Zezima"));
	}

	/**
	 * The client hands back player names using non-breaking spaces, so config typed with ordinary
	 * spaces has to match them.
	 */
	@Test
	public void nameMatchingHandlesNonBreakingSpacesFromTheClient()
	{
		final MemberRules rules = parse("Iron Mammal", "Iron Mammal=2015-03-14");

		// U+00A0, which is what ClanMember.getName() actually returns in place of a space.
		final String fromClient = "Iron\u00A0Mammal";

		assertTrue(rules.isIgnored(fromClient));
		assertEquals(LocalDate.of(2015, 3, 14), rules.joinDateFor(fromClient));
	}

	@Test
	public void manualJoinDateParsesIsoAndSlashForms()
	{
		final MemberRules rules = parse("", "Zezima=2015-03-14\nWoox=2018/11/02");

		assertEquals(LocalDate.of(2015, 3, 14), rules.joinDateFor("Zezima"));
		assertEquals(LocalDate.of(2018, 11, 2), rules.joinDateFor("Woox"));
		assertEquals(0, rules.getWarnings().size());
	}

	@Test
	public void acceptsDateEqualsNameAsWellAsNameEqualsDate()
	{
		final MemberRules rules = parse("", "2015-03-14=Zezima");

		assertEquals(LocalDate.of(2015, 3, 14), rules.joinDateFor("Zezima"));
		assertEquals(0, rules.getWarnings().size());
	}

	@Test
	public void warnsOnUnparseableDateRatherThanGuessingTheFormat()
	{
		final MemberRules rules = parse("", "Zezima=14/03/2015\nWoox=last tuesday\nBoaty");

		assertNull(rules.joinDateFor("Zezima"));
		assertNull(rules.joinDateFor("Woox"));
		assertTrue(containing(rules.getWarnings(), "Name=YYYY-MM-DD"));
		assertEquals(3, rules.getWarnings().size());
	}

	@Test
	public void warnsOnFutureJoinDate()
	{
		final MemberRules rules = parse("", "Zezima=2027-01-01");

		assertTrue(containing(rules.getWarnings(), "in the future"));
	}

	@Test
	public void warnsOnDuplicateIgnoredEntry()
	{
		final MemberRules rules = parse("Zezima, zezima", "");

		assertTrue(containing(rules.getWarnings(), "listed twice"));
	}

	@Test
	public void warnsOnConflictingJoinDatesAndKeepsTheLast()
	{
		final MemberRules rules = parse("", "Zezima=2015-03-14\nZezima=2016-01-01");

		assertEquals(LocalDate.of(2016, 1, 1), rules.joinDateFor("Zezima"));
		assertTrue(containing(rules.getWarnings(), "more than one manual join date"));
	}

	@Test
	public void warnsWhenAMemberIsBothIgnoredAndGivenAJoinDate()
	{
		final MemberRules rules = parse("Zezima", "Zezima=2015-03-14");

		assertTrue(containing(rules.getWarnings(), "also ignored"));
	}

	@Test
	public void commentLinesAreSkipped()
	{
		final MemberRules rules = parse("# alts\nAlt One", "// rejoined members\nZezima=2015-03-14");

		assertTrue(rules.isIgnored("Alt One"));
		assertFalse(rules.isIgnored("# alts"));
		assertEquals(LocalDate.of(2015, 3, 14), rules.joinDateFor("Zezima"));
	}

	@Test
	public void namesMatchingNobodyInTheClanAreReported()
	{
		final MemberRules rules = parse("Typoed Nmae", "Zezima=2015-03-14");
		final Set<String> roster = names("zezima", "woox");

		final List<String> warnings = ClanTenureService.validateAgainstRoster(rules, roster);

		assertEquals(1, warnings.size());
		assertTrue("warning should quote the name as typed: " + warnings.get(0),
			warnings.get(0).contains("Typoed Nmae"));
	}

	@Test
	public void noRosterWarningsWhenEveryNameMatches()
	{
		final MemberRules rules = parse("Alt One", "Zezima=2015-03-14");
		final Set<String> roster = names("zezima", "alt one");

		assertEquals(0, ClanTenureService.validateAgainstRoster(rules, roster).size());
	}

	@Test
	public void rosterCheckIsSkippedBeforeTheRosterLoads()
	{
		final MemberRules rules = parse("Alt One", "");

		assertEquals(0, ClanTenureService.validateAgainstRoster(rules, Collections.emptySet()).size());
	}

	private static Set<String> names(String... values)
	{
		return new HashSet<>(Arrays.asList(values));
	}

	private static boolean containing(List<String> warnings, String fragment)
	{
		return warnings.stream().anyMatch(w -> w.contains(fragment));
	}
}

package com.clantenure;

import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class RankLadderTest
{
	private static RankLadder defaultLadder()
	{
		return RankLadder.parse(ClanTenureConfig.DEFAULT_ELIGIBLE_RANKS, ClanTenureConfig.DEFAULT_THRESHOLDS);
	}

	@Test
	public void parsesTheShippedDefaultsCleanly()
	{
		final RankLadder ladder = defaultLadder();

		assertEquals("no warnings expected for the default config: " + ladder.getWarnings(),
			0, ladder.getWarnings().size());
		assertEquals(9, ladder.size());
		assertEquals("Jade", ladder.nameAt(0));
		assertEquals("Zenyte", ladder.nameAt(8));
	}

	@Test
	public void entryRankSitsAtZeroDaysAndThresholdsMatchConfig()
	{
		final RankLadder ladder = defaultLadder();

		assertEquals(0, ladder.thresholdAt(0));
		assertEquals(120, ladder.thresholdAt(1));
		assertEquals(240, ladder.thresholdAt(2));
		assertEquals(365, ladder.thresholdAt(3));
		assertEquals(485, ladder.thresholdAt(4));
		assertEquals(605, ladder.thresholdAt(5));
		assertEquals(730, ladder.thresholdAt(6));
		assertEquals(910, ladder.thresholdAt(7));
		assertEquals(1095, ladder.thresholdAt(8));
	}

	@Test
	public void rankNamesMatchIgnoringCaseAndExtraWhitespace()
	{
		final RankLadder ladder = defaultLadder();

		assertEquals(1, ladder.indexOf("red topaz").getAsInt());
		assertEquals(1, ladder.indexOf("  RED   TOPAZ ").getAsInt());
		assertFalse(ladder.indexOf("Deputy Owner").isPresent());
		assertFalse(ladder.indexOf(null).isPresent());
	}

	@Test
	public void acceptsCommasNewlinesAndComments()
	{
		final RankLadder ladder = RankLadder.parse(
			"# the ladder\nJade\nRed Topaz, Sapphire\n",
			"// thresholds\n120=Red Topaz\n240=Sapphire");

		assertEquals(3, ladder.size());
		assertEquals(120, ladder.thresholdAt(1));
		assertEquals(240, ladder.thresholdAt(2));
		assertEquals(0, ladder.getWarnings().size());
	}

	@Test
	public void acceptsNameEqualsDaysAsWellAsDaysEqualsName()
	{
		final RankLadder ladder = RankLadder.parse("Jade, Sapphire", "Sapphire = 240");

		assertEquals(240, ladder.thresholdAt(1));
		assertEquals(0, ladder.getWarnings().size());
	}

	@Test
	public void warnsWhenAThresholdNamesARankThatIsNotEligible()
	{
		final RankLadder ladder = RankLadder.parse("Jade, Sapphire", "120=Red Topaz\n240=Sapphire");

		assertTrue(containing(ladder.getWarnings(), "not in your eligible ranks"));
	}

	@Test
	public void warnsOnDuplicateEligibleRankAndKeepsOneRung()
	{
		final RankLadder ladder = RankLadder.parse("Jade, Sapphire, sapphire", "240=Sapphire");

		assertEquals(2, ladder.size());
		assertTrue(containing(ladder.getWarnings(), "Duplicate eligible rank"));
	}

	@Test
	public void warnsOnMalformedThresholdLines()
	{
		final RankLadder ladder = RankLadder.parse("Jade, Sapphire", "Sapphire\n=\nabc=Sapphire");

		assertTrue(containing(ladder.getWarnings(), "expected the form"));
		assertTrue(containing(ladder.getWarnings(), "neither side is a number"));
	}

	@Test
	public void warnsWhenAMidLadderRankHasNoThreshold()
	{
		final RankLadder ladder = RankLadder.parse("Jade, Red Topaz, Sapphire", "240=Sapphire");

		assertTrue(containing(ladder.getWarnings(), "\"Red Topaz\" has no tenure threshold"));
	}

	@Test
	public void warnsWhenAHigherRankNeedsNoMoreTimeThanALowerOne()
	{
		final RankLadder ladder = RankLadder.parse("Jade, Red Topaz, Sapphire", "240=Red Topaz\n120=Sapphire");

		assertTrue(containing(ladder.getWarnings(), "requires no more time than"));
	}

	@Test
	public void warnsWhenTheEntryRankIsGivenAThreshold()
	{
		final RankLadder ladder = RankLadder.parse("Jade, Sapphire", "30=Jade\n240=Sapphire");

		assertTrue(containing(ladder.getWarnings(), "treated as the entry rank"));
		assertEquals(0, ladder.thresholdAt(0));
	}

	@Test
	public void warnsOnDuplicateThresholdAndKeepsTheFirst()
	{
		final RankLadder ladder = RankLadder.parse("Jade, Sapphire", "240=Sapphire\n999=Sapphire");

		assertEquals(240, ladder.thresholdAt(1));
		assertTrue(containing(ladder.getWarnings(), "Duplicate threshold"));
	}

	@Test
	public void clampsNegativeThresholdsToZero()
	{
		final RankLadder ladder = RankLadder.parse("Jade, Sapphire", "-5=Sapphire");

		assertEquals(0, ladder.thresholdAt(1));
		assertTrue(containing(ladder.getWarnings(), "negative"));
	}

	@Test
	public void emptyConfigIsUnusableRatherThanCrashing()
	{
		final RankLadder ladder = RankLadder.parse("", "");

		assertFalse(ladder.isUsable());
		assertTrue(containing(ladder.getWarnings(), "No eligible ranks"));
	}

	@Test
	public void nullConfigIsTreatedAsEmpty()
	{
		final RankLadder ladder = RankLadder.parse(null, null);

		assertFalse(ladder.isUsable());
	}

	@Test
	public void earnedIndexPicksTheHighestRankReached()
	{
		final RankLadder ladder = defaultLadder();

		assertEquals(0, ladder.earnedIndex(0));
		assertEquals(0, ladder.earnedIndex(119));
		assertEquals(1, ladder.earnedIndex(120));
		assertEquals(1, ladder.earnedIndex(239));
		assertEquals(2, ladder.earnedIndex(240));
		assertEquals(8, ladder.earnedIndex(1095));
		assertEquals(8, ladder.earnedIndex(50_000));
	}

	private static boolean containing(List<String> warnings, String fragment)
	{
		return warnings.stream().anyMatch(w -> w.contains(fragment));
	}
}

package com.clantenure;

import java.time.LocalDate;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class PromotionWatcherTest
{
	private static final LocalDate TODAY = LocalDate.of(2026, 8, 6);
	private static final RankLadder LADDER =
		RankLadder.parse(ClanTenureConfig.DEFAULT_ELIGIBLE_RANKS, ClanTenureConfig.DEFAULT_THRESHOLDS);

	private PromotionWatcher watcher;

	@Before
	public void setUp()
	{
		watcher = new PromotionWatcher();
	}

	private static MemberTenure due(String name)
	{
		return ClanTenureService.evaluate(name, TODAY.minusDays(1204), "Onyx", LADDER, TODAY);
	}

	private static MemberTenure correct(String name)
	{
		return ClanTenureService.evaluate(name, TODAY.minusDays(400), "Emerald", LADDER, TODAY);
	}

	private static ClanSnapshot snapshot(String clanName, MemberTenure... members)
	{
		return new ClanSnapshot(ClanSnapshot.State.OK, clanName, Arrays.asList(members), Collections.emptyList());
	}

	@Test
	public void firstSuccessfulRefreshSeedsWithoutReportingAnybody()
	{
		final List<MemberTenure> newlyDue = watcher.update(snapshot("My Clan", due("Zezima"), due("Woox")));

		assertTrue("first refresh should not flood notifications for an already-overdue roster",
			newlyDue.isEmpty());
	}

	@Test
	public void memberBecomingDueAfterASeededRefreshIsReported()
	{
		watcher.update(snapshot("My Clan", correct("Zezima")));

		final List<MemberTenure> newlyDue = watcher.update(snapshot("My Clan", due("Zezima")));

		assertEquals(1, newlyDue.size());
		assertEquals("Zezima", newlyDue.get(0).getName());
	}

	@Test
	public void memberStayingDueAcrossRefreshesIsNotReportedAgain()
	{
		watcher.update(snapshot("My Clan", due("Zezima")));

		final List<MemberTenure> newlyDue = watcher.update(snapshot("My Clan", due("Zezima")));

		assertTrue(newlyDue.isEmpty());
	}

	@Test
	public void memberWhoDropsOffAndBecomesDueAgainIsReportedTheSecondTime()
	{
		watcher.update(snapshot("My Clan", due("Zezima")));
		watcher.update(snapshot("My Clan", correct("Zezima")));

		final List<MemberTenure> newlyDue = watcher.update(snapshot("My Clan", due("Zezima")));

		assertEquals(1, newlyDue.size());
	}

	@Test
	public void switchingToADifferentClanReseedsWithoutReporting()
	{
		watcher.update(snapshot("My Clan", correct("Zezima")));

		final List<MemberTenure> newlyDue = watcher.update(snapshot("Other Clan", due("Woox")));

		assertTrue("a different clan has no baseline to compare against yet", newlyDue.isEmpty());
	}

	@Test
	public void nonOkSnapshotsAreIgnoredAndDoNotResetTheBaseline()
	{
		watcher.update(snapshot("My Clan", correct("Zezima")));

		watcher.update(ClanSnapshot.empty(ClanSnapshot.State.LOGGED_OUT, Collections.emptyList()));

		final List<MemberTenure> newlyDue = watcher.update(snapshot("My Clan", due("Zezima")));

		assertEquals("a logout blip in between should not have cleared the baseline", 1, newlyDue.size());
	}

	@Test
	public void nameMatchingIgnoresCaseSoAConfigTypoDoesNotDoubleReport()
	{
		watcher.update(snapshot("My Clan", correct("Zezima")));
		watcher.update(snapshot("My Clan", due("Zezima")));

		final List<MemberTenure> newlyDue = watcher.update(snapshot("My Clan", due("zezima")));

		assertTrue(newlyDue.isEmpty());
	}

	@Test
	public void singleMemberMessageNamesThemAndTheirEarnedRank()
	{
		final String message = PromotionWatcher.message(Collections.singletonList(due("Zezima")));

		assertEquals("Zezima is now due a promotion to Zenyte.", message);
	}

	@Test
	public void smallBatchMessageListsEveryName()
	{
		final String message = PromotionWatcher.message(Arrays.asList(due("Zezima"), due("Woox")));

		assertEquals("2 members are now due a promotion: Zezima, Woox", message);
	}

	@Test
	public void largeBatchMessageCollapsesToACountInsteadOfListingEveryName()
	{
		final List<MemberTenure> many = Arrays.asList(
			due("A"), due("B"), due("C"), due("D"), due("E"), due("F"));

		final String message = PromotionWatcher.message(many);

		assertEquals("6 members are now due a promotion - check the Clan Tenure Ranks panel.", message);
	}
}

package com.clantenure;

import java.time.LocalDate;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * Drives {@link ClanTenureService#evaluate} directly, so the promotion rules are proven without a
 * running game client.
 */
public class TenureLogicTest
{
	private static final LocalDate TODAY = LocalDate.of(2026, 8, 6);

	private static final RankLadder LADDER =
		RankLadder.parse(ClanTenureConfig.DEFAULT_ELIGIBLE_RANKS, ClanTenureConfig.DEFAULT_THRESHOLDS);

	private static MemberTenure evaluate(String currentRank, long daysInClan)
	{
		return ClanTenureService.evaluate("Player", TODAY.minusDays(daysInClan), currentRank, LADDER, TODAY);
	}

	@Test
	public void memberAtTheRightRankIsCorrect()
	{
		final MemberTenure member = evaluate("Emerald", 400);

		assertEquals(TenureStatus.CORRECT, member.getStatus());
		assertEquals("Emerald", member.getEarnedRank());
		assertEquals(400, member.getTenureDays());
	}

	@Test
	public void memberBehindTheirTenureIsDueAPromotion()
	{
		final MemberTenure member = evaluate("Onyx", 1204);

		assertEquals(TenureStatus.DUE_PROMOTION, member.getStatus());
		assertEquals("Zenyte", member.getEarnedRank());
	}

	@Test
	public void memberAheadOfTheirTenureIsOverRanked()
	{
		final MemberTenure member = evaluate("Onyx", 700);

		assertEquals(TenureStatus.OVER_RANKED, member.getStatus());
		assertEquals("Diamond", member.getEarnedRank());
	}

	@Test
	public void thresholdBoundaryIsInclusiveOnTheDayItIsReached()
	{
		assertEquals(TenureStatus.CORRECT, evaluate("Jade", 119).getStatus());
		assertEquals(TenureStatus.DUE_PROMOTION, evaluate("Jade", 120).getStatus());
		assertEquals("Red Topaz", evaluate("Jade", 120).getEarnedRank());
		assertEquals("Red Topaz", evaluate("Jade", 121).getEarnedRank());
	}

	@Test
	public void topOfTheLadderStaysAtTheTop()
	{
		final MemberTenure member = evaluate("Zenyte", 4000);

		assertEquals(TenureStatus.CORRECT, member.getStatus());
		assertEquals("Zenyte", member.getEarnedRank());
	}

	@Test
	public void brandNewMemberFloorsAtTheEntryRank()
	{
		final MemberTenure member = evaluate("Jade", 0);

		assertEquals(TenureStatus.CORRECT, member.getStatus());
		assertEquals("Jade", member.getEarnedRank());
		assertEquals(0, member.getTenureDays());
	}

	@Test
	public void offLadderRanksAreLeftAlone()
	{
		for (String staffRank : new String[]{"Owner", "Deputy Owner", "Administrator", "Event Team"})
		{
			final MemberTenure member = evaluate(staffRank, 4000);

			assertEquals(staffRank + " should not be tracked", TenureStatus.NOT_TRACKED, member.getStatus());
			assertNull(member.getEarnedRank());
		}
	}

	@Test
	public void memberWithNoRankTitleIsNotTracked()
	{
		final MemberTenure member = ClanTenureService.evaluate("Player", TODAY.minusDays(500), null, LADDER, TODAY);

		assertEquals(TenureStatus.NOT_TRACKED, member.getStatus());
	}

	@Test
	public void missingJoinDateOnALadderRankIsReportedRatherThanGuessed()
	{
		final MemberTenure member = ClanTenureService.evaluate("Player", null, "Emerald", LADDER, TODAY);

		assertEquals(TenureStatus.UNKNOWN, member.getStatus());
		assertEquals(0, member.getTenureDays());
		assertNull(member.getEarnedRank());
		assertNull(member.getJoinDate());
	}

	@Test
	public void offLadderRankWinsOverAMissingJoinDate()
	{
		final MemberTenure member = ClanTenureService.evaluate("Player", null, "Owner", LADDER, TODAY);

		assertEquals(TenureStatus.NOT_TRACKED, member.getStatus());
	}

	@Test
	public void rankNameFromTheClientIsMatchedCaseInsensitively()
	{
		final MemberTenure member = evaluate("dragonstone", 800);

		assertEquals(TenureStatus.CORRECT, member.getStatus());
	}

	/**
	 * The point of a manual join date: backdating someone makes them due the rank their real tenure
	 * has earned, even though the game reports them as newer.
	 */
	@Test
	public void olderManualJoinDatePromotesAMemberTheGameDateWouldNot()
	{
		final LocalDate gameDate = TODAY.minusDays(100);
		final LocalDate backdated = TODAY.minusDays(400);

		final MemberTenure fromGame = ClanTenureService.evaluate("Player", gameDate, "Jade", LADDER, TODAY);
		assertEquals(TenureStatus.CORRECT, fromGame.getStatus());

		final MemberTenure overridden =
			ClanTenureService.evaluate("Player", backdated, "Jade", LADDER, TODAY, true);

		assertEquals(TenureStatus.DUE_PROMOTION, overridden.getStatus());
		assertEquals("Emerald", overridden.getEarnedRank());
		assertEquals(400, overridden.getTenureDays());
		assertTrue(overridden.isJoinDateOverridden());
	}

	@Test
	public void joinDatesFromTheGameAreNotMarkedAsManual()
	{
		assertFalse(evaluate("Emerald", 400).isJoinDateOverridden());
	}

	@Test
	public void futureJoinDateClampsToZeroInsteadOfGoingNegative()
	{
		final MemberTenure member = ClanTenureService.evaluate("Player", TODAY.plusDays(30), "Jade", LADDER, TODAY);

		assertEquals(0, member.getTenureDays());
		assertEquals(TenureStatus.CORRECT, member.getStatus());
	}
}

package com.clantenure;

import java.awt.Color;
import lombok.Getter;

/**
 * How a member's current clan rank compares to the rank their tenure has earned them.
 */
@Getter
public enum TenureStatus
{
	/**
	 * The member holds a lower rank than their tenure earns. These are the promotions to action.
	 */
	DUE_PROMOTION("Due promotion", new Color(76, 175, 80)),
	/**
	 * The member's rank matches their tenure exactly.
	 */
	CORRECT("Correct", new Color(150, 150, 150)),
	/**
	 * The member holds a higher rank than their tenure earns - promoted early, or by mistake.
	 */
	OVER_RANKED("Over-ranked", new Color(255, 152, 0)),
	/**
	 * The member's current rank is not on the eligible-ranks ladder, so tenure does not apply to
	 * them. Staff and event ranks land here.
	 */
	NOT_TRACKED("Not tracked", new Color(110, 110, 110)),
	/**
	 * The clan roster gave us no join date for this member, so tenure cannot be calculated.
	 */
	UNKNOWN("No join date", new Color(200, 80, 80)),
	/**
	 * Listed under ignored members, so left out of every count and filter.
	 */
	IGNORED("Ignored", new Color(110, 110, 110));

	private final String label;
	private final Color color;

	TenureStatus(String label, Color color)
	{
		this.label = label;
		this.color = color;
	}
}

package com.clantenure;

import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * Tracks which members were due a promotion on the last successful refresh, so the plugin can
 * notify only about members who newly cross a threshold - not the whole roster every time the
 * panel refreshes.
 */
class PromotionWatcher
{
	private static final int MAX_NAMES_IN_MESSAGE = 5;

	private boolean seeded;
	private String clanName;
	private Set<String> lastDue = Collections.emptySet();

	/**
	 * Returns the members who are due a promotion now but were not on the last successful refresh of
	 * the same clan. The very first successful refresh, and any refresh for a different clan than
	 * last time (an account switch), seed the baseline silently rather than reporting everyone who
	 * was already overdue. A refresh that failed to load the roster (logged out, no clan, etc.)
	 * leaves the baseline untouched, so a brief blip does not reset it.
	 */
	List<MemberTenure> update(ClanSnapshot snapshot)
	{
		if (snapshot.getState() != ClanSnapshot.State.OK)
		{
			return Collections.emptyList();
		}

		final boolean sameClan = seeded && Objects.equals(clanName, snapshot.getClanName());

		final List<MemberTenure> newlyDue = !sameClan ? Collections.emptyList()
			: snapshot.getMembers().stream()
				.filter(m -> m.getStatus() == TenureStatus.DUE_PROMOTION)
				.filter(m -> !lastDue.contains(ConfigText.normalize(m.getName())))
				.collect(Collectors.toList());

		clanName = snapshot.getClanName();
		seeded = true;
		lastDue = snapshot.getMembers().stream()
			.filter(m -> m.getStatus() == TenureStatus.DUE_PROMOTION)
			.map(m -> ConfigText.normalize(m.getName()))
			.collect(Collectors.toCollection(HashSet::new));

		return newlyDue;
	}

	/**
	 * A notification message for the given newly-due members. Long lists collapse into a count
	 * rather than a wall of names, since a bulk change (e.g. editing thresholds) can otherwise turn
	 * one config edit into a dozen tray popups.
	 */
	static String message(List<MemberTenure> newlyDue)
	{
		if (newlyDue.size() == 1)
		{
			final MemberTenure member = newlyDue.get(0);
			return member.getName() + " is now due a promotion to " + member.getEarnedRank() + ".";
		}
		if (newlyDue.size() <= MAX_NAMES_IN_MESSAGE)
		{
			final String names = newlyDue.stream().map(MemberTenure::getName).collect(Collectors.joining(", "));
			return newlyDue.size() + " members are now due a promotion: " + names;
		}
		return newlyDue.size() + " members are now due a promotion - check the Clan Tenure Ranks panel.";
	}
}

package com.clantenure;

import java.util.Collections;
import java.util.List;
import javax.annotation.Nullable;
import lombok.Value;

/**
 * Everything the panel needs for one render: why there is or isn't data, the evaluated roster, and
 * any config problems worth showing the user.
 */
@Value
public class ClanSnapshot
{
	public enum State
	{
		/** Not logged in, so the client holds no clan data. */
		LOGGED_OUT,
		/** Logged in, but the account is not in a clan. */
		NO_CLAN,
		/** Roster present but every member is missing a join date. */
		NO_JOIN_DATES,
		/** The eligible-ranks config is empty, so nothing can be compared. */
		NO_LADDER,
		/** Usable data. */
		OK
	}

	State state;

	@Nullable
	String clanName;

	List<MemberTenure> members;

	/**
	 * Config problems (bad thresholds, names that match no real clan title, ordering mistakes).
	 */
	List<String> warnings;

	public static ClanSnapshot empty(State state, List<String> warnings)
	{
		return new ClanSnapshot(state, null, Collections.emptyList(), warnings);
	}

	public long count(TenureStatus status)
	{
		return members.stream().filter(m -> m.getStatus() == status).count();
	}

	/**
	 * Members the ladder actually applies to - excluding off-ladder ranks and ignored members.
	 */
	public long trackedCount()
	{
		return members.stream()
			.filter(m -> m.getStatus() != TenureStatus.NOT_TRACKED && m.getStatus() != TenureStatus.IGNORED)
			.count();
	}
}

package com.clantenure;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;

/**
 * Per-member exceptions: manual join dates that replace the in-game one, and members to leave out
 * of the report entirely.
 *
 * <p>Both are keyed on the normalised player name, so case and spacing do not have to match what
 * the game reports. As with {@link RankLadder}, parsing never throws - problems become warnings.
 */
public final class MemberRules
{
	/** Normalised names of members left out of the report entirely. */
	private final Set<String> ignored;

	/** Normalised name -> manual join date. */
	private final Map<String, LocalDate> joinDates;

	/** Normalised name -> the name as the user typed it, so warnings can quote it back. */
	private final Map<String, String> displayNames;

	private final List<String> warnings;

	private MemberRules(Set<String> ignored, Map<String, LocalDate> joinDates, Map<String, String> displayNames,
		List<String> warnings)
	{
		this.ignored = Collections.unmodifiableSet(ignored);
		this.joinDates = Collections.unmodifiableMap(joinDates);
		this.displayNames = Collections.unmodifiableMap(displayNames);
		this.warnings = Collections.unmodifiableList(warnings);
	}

	public static MemberRules parse(String ignoredConfig, String joinDateConfig, LocalDate today)
	{
		final List<String> warnings = new ArrayList<>();
		final Set<String> ignored = new LinkedHashSet<>();
		final Map<String, LocalDate> joinDates = new LinkedHashMap<>();
		final Map<String, String> displayNames = new LinkedHashMap<>();

		for (String entry : ConfigText.entries(ignoredConfig))
		{
			final String key = ConfigText.normalize(entry);
			displayNames.putIfAbsent(key, entry);
			if (!ignored.add(key))
			{
				warnings.add("\"" + entry + "\" is listed twice under ignored members.");
			}
		}

		for (String entry : ConfigText.entries(joinDateConfig))
		{
			parseJoinDate(entry, joinDates, ignored, displayNames, warnings, today);
		}

		return new MemberRules(ignored, joinDates, displayNames, warnings);
	}

	private static void parseJoinDate(String entry, Map<String, LocalDate> joinDates, Set<String> ignored,
		Map<String, String> displayNames, List<String> warnings, LocalDate today)
	{
		final String[] pair = ConfigText.splitPair(entry);
		if (pair == null)
		{
			warnings.add("Skipped join date \"" + entry + "\": expected the form Name=YYYY-MM-DD.");
			return;
		}

		// The documented form is Name=date, but a date is never a valid name so the two can be given
		// either way round without ambiguity.
		String name = pair[0];
		LocalDate date = tryParseDate(pair[1]);
		if (date == null)
		{
			date = tryParseDate(pair[0]);
			name = pair[1];
		}

		if (date == null)
		{
			warnings.add("Skipped join date \"" + entry + "\": use the form Name=YYYY-MM-DD, for example "
				+ "Zezima=2015-03-14.");
			return;
		}
		if (name.isEmpty())
		{
			warnings.add("Skipped join date \"" + entry + "\": no player name given.");
			return;
		}
		if (date.isAfter(today))
		{
			warnings.add("Manual join date for \"" + name + "\" is in the future, so their tenure will be 0.");
		}

		final String key = ConfigText.normalize(name);
		displayNames.putIfAbsent(key, name);

		if (ignored.contains(key))
		{
			warnings.add("\"" + name + "\" has a manual join date but is also ignored, so the date is unused.");
		}

		if (joinDates.put(key, date) != null)
		{
			warnings.add("\"" + name + "\" has more than one manual join date; using " + date + ".");
		}
	}

	@Nullable
	private static LocalDate tryParseDate(String value)
	{
		final String cleaned = value.trim().replace('/', '-');
		if (cleaned.isEmpty())
		{
			return null;
		}
		try
		{
			return LocalDate.parse(cleaned);
		}
		catch (DateTimeParseException e)
		{
			return null;
		}
	}

	public boolean isIgnored(String name)
	{
		return name != null && ignored.contains(ConfigText.normalize(name));
	}

	/**
	 * The manual join date for this member, or null to use the one the game reports.
	 */
	@Nullable
	public LocalDate joinDateFor(String name)
	{
		return name == null ? null : joinDates.get(ConfigText.normalize(name));
	}

	public boolean isEmpty()
	{
		return ignored.isEmpty() && joinDates.isEmpty();
	}

	/**
	 * Normalised name to the name as typed, for every member referenced by either list. The service
	 * uses this to warn about names matching nobody in the clan - a typo would otherwise fail
	 * silently.
	 */
	public Map<String, String> referencedNames()
	{
		return displayNames;
	}

	public List<String> getWarnings()
	{
		return warnings;
	}
}

package com.clantenure;

import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.List;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.events.ClanChannelChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Clan Tenure Ranks",
	description = "Shows which clan members are due a rank promotion based on how long they have been in the clan",
	tags = {"clan", "rank", "tenure", "promotion", "members"}
)
public class ClanTenurePlugin extends Plugin
{
	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ClanTenureConfig config;

	@Inject
	private ClanTenureService service;

	@Inject
	private Notifier notifier;

	private ClanTenurePanel panel;
	private NavigationButton navButton;
	private PromotionWatcher promotionWatcher;

	@Override
	protected void startUp()
	{
		panel = new ClanTenurePanel(this::refresh);
		promotionWatcher = new PromotionWatcher();

		final BufferedImage icon = ImageUtil.loadImageResource(ClanTenurePlugin.class, "panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Clan Tenure Ranks")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		refresh();
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
		promotionWatcher = null;
	}

	/**
	 * The roster arrives shortly after login, and this is the event that tells us it is ready.
	 */
	@Subscribe
	public void onClanChannelChanged(ClanChannelChanged event)
	{
		if (!event.isGuest())
		{
			refresh();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN || state == GameState.LOGIN_SCREEN)
		{
			refresh();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (ClanTenureConfig.GROUP.equals(event.getGroup()))
		{
			refresh();
		}
	}

	/**
	 * Parses the ladder off the calling thread, reads the roster on the client thread, then hands the
	 * finished snapshot to Swing.
	 */
	void refresh()
	{
		final ClanTenurePanel target = panel;
		if (target == null)
		{
			return;
		}

		final RankLadder ladder = RankLadder.parse(config.eligibleRanks(), config.tenureThresholds());
		final MemberRules rules = MemberRules.parse(config.ignoredMembers(), config.joinDateOverrides(),
			LocalDate.now(ZoneOffset.UTC));
		final boolean notifyEnabled = config.notifyOnPromotion();

		clientThread.invoke(() ->
		{
			final ClanSnapshot snapshot = service.snapshot(ladder, rules);

			// promotionWatcher tracks the previous refresh regardless of the toggle, so switching
			// notifications on does not immediately dump a backlog of everyone already due.
			final PromotionWatcher watcher = promotionWatcher;
			if (watcher != null)
			{
				final List<MemberTenure> newlyDue = watcher.update(snapshot);
				if (notifyEnabled && !newlyDue.isEmpty())
				{
					notifier.notify(PromotionWatcher.message(newlyDue));
				}
			}

			SwingUtilities.invokeLater(() -> target.display(snapshot));
		});
	}

	@Provides
	ClanTenureConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ClanTenureConfig.class);
	}
}

